/**
 * 🆕 V4: Create a new employeeSalaryEntry with enhanced features
 * - Text foreign key support
 * - Complex validation
 * - Business logic calculations
 */
export async function createEmployeeSalaryEntry(data: CreateEmployeeSalaryEntryInput): Promise<EmployeeSalaryEntryDb> {
  // 🆕 V4: Validate foreign keys exist (supporting both text and integer FKs)

  if (data.userId) {
    const userSyncExists = await db
      .select({ userId: userSyncSchema.userId })
      .from(userSyncSchema)
      .where(eq(userSyncSchema.userId, data.userId))
      .limit(1);

    if (!userSyncExists.length) {
      throw new Error('UserSync not found');
    }
  }
  if (data.productionStepDetailId) {
    const productionStepDetailExists = await db
      .select({ id: productionStepDetailSchema.id })
      .from(productionStepDetailSchema)
      .where(eq(productionStepDetailSchema.id, data.productionStepDetailId))
      .limit(1);

    if (!productionStepDetailExists.length) {
      throw new Error('ProductionStepDetail not found');
    }
  }
  if (data.planId) {
    const planExists = await db
      .select({ id: planSchema.id })
      .from(planSchema)
      .where(eq(planSchema.id, data.planId))
      .limit(1);

    if (!planExists.length) {
      throw new Error('Plan not found');
    }
  }

  //  V4: Business logic - Auto-calculate total amount
  if (data.actualQuantity && data.unitPrice && !data.totalAmount) {
    data.totalAmount = Number(data.actualQuantity ?? 0) * Number(data.unitPrice ?? 0);
  }

  const [employeeSalaryEntry] = await db
    .insert(employeeSalaryEntrySchema)
    .values({
      work_date: data.workDate ? new Date(data.workDate) : null,
      entry_date: data.entryDate ? new Date(data.entryDate) : null,
      actual_quantity: data.actualQuantity,
      planned_quantity: data.plannedQuantity,
      limit_quantity: data.limitQuantity,
      previous_entered_quantity: data.previousEnteredQuantity,
      unit_price: data.unitPrice,
      total_amount: data.totalAmount,
      salary_note: data.salaryNote,
      status: data.status,
      approved_by: data.approvedBy,
      approved_at: data.approvedAt ? new Date(data.approvedAt) : null,
      start_time: data.startTime ? new Date(data.startTime) : null,
      end_time: data.endTime ? new Date(data.endTime) : null,
      work_duration_minutes: data.workDurationMinutes,
      owner_id: data.ownerId,
      user_id: data.userId,
      production_step_detail_id: data.productionStepDetailId,
      plan_id: data.planId,
    } as any)
    .returning();

  if (!employeeSalaryEntry) {
    throw new Error('Failed to create employeeSalaryEntry');
  }

  return employeeSalaryEntry;
}

