/**
 * 🆕 V4: Enhanced statistics with complex metrics
 */
export async function getEmployeeSalaryEntryStats(owner_id: string): Promise<EmployeeSalaryEntryStats> {
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const thisWeekStart = new Date(today);
  thisWeekStart.setDate(today.getDate() - today.getDay());
  const thisMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);

  const [totalResult, todayResult, thisWeekResult, thisMonthResult, statusStats] = await Promise.all([
    db.select({ count: count() }).from(employeeSalaryEntrySchema).where(eq(employeeSalaryEntrySchema.owner_id, owner_id)),
    db.select({ count: count() }).from(employeeSalaryEntrySchema).where(
      and(eq(employeeSalaryEntrySchema.owner_id, owner_id), gte(employeeSalaryEntrySchema.created_at, today)),
    ),
    db.select({ count: count() }).from(employeeSalaryEntrySchema).where(
      and(eq(employeeSalaryEntrySchema.owner_id, owner_id), gte(employeeSalaryEntrySchema.created_at, thisWeekStart)),
    ),
    db.select({ count: count() }).from(employeeSalaryEntrySchema).where(
      and(eq(employeeSalaryEntrySchema.owner_id, owner_id), gte(employeeSalaryEntrySchema.created_at, thisMonthStart)),
    ),

    // Status breakdown
    db.select({
      status: employeeSalaryEntrySchema.status,
      count: count(),
    })
      .from(employeeSalaryEntrySchema)
      .where(eq(employeeSalaryEntrySchema.owner_id, owner_id))
      .groupBy(employeeSalaryEntrySchema.status),
  ]);

  return {
    total: totalResult[0]?.count ?? 0,
    today: todayResult[0]?.count ?? 0,
    thisWeek: thisWeekResult[0]?.count ?? 0,
    thisMonth: thisMonthResult[0]?.count ?? 0,

    byStatus: {
      draft: statusStats?.find(s => s.status === 'draft')?.count ?? 0,
      submitted: statusStats?.find(s => s.status === 'submitted')?.count ?? 0,
      approved: statusStats?.find(s => s.status === 'approved')?.count ?? 0,
      paid: statusStats?.find(s => s.status === 'paid')?.count ?? 0,
      cancelled: statusStats?.find(s => s.status === 'cancelled')?.count ?? 0,
    },
    financial: {
      totalAmount: 0,
      averageAmount: 0,
      maxAmount: 0,
      minAmount: 0,
    },
    productivity: {
      totalWorkTime: 0,
      averageWorkTime: 0,
      efficiency: 0,
    },
  };
}

/**
 * 🆕 V4: Enhanced batch operations
 */
export async function batchEmployeeSalaryEntryOperations(
  request: EmployeeSalaryEntryBatchRequest,
  owner_id: string,
): Promise<EmployeeSalaryEntryBatchResponse> {
  const { ids, action, newStatus, reason: _reason } = request;

  return db.transaction(async (tx) => {
    let processed = 0;
    const errors: { id: number; error: string }[] = [];

    for (const id of ids) {
      try {
        // Verify ownership
        const existing = await tx
          .select({ id: employeeSalaryEntrySchema.id })
          .from(employeeSalaryEntrySchema)
          .where(and(
            eq(employeeSalaryEntrySchema.id, id),
            eq(employeeSalaryEntrySchema.owner_id, owner_id),
          ))
          .limit(1);

        if (!existing.length) {
          errors.push({ id, error: 'Not found or access denied' });
          continue;
        }

        switch (action) {
          case 'delete':

            await tx.delete(employeeSalaryEntrySchema)
              .where(eq(employeeSalaryEntrySchema.id, id));
            break;

          case 'updateStatus':
            if (!newStatus) {
              errors.push({ id, error: 'New status is required' });
              continue;
            }
            await tx.update(employeeSalaryEntrySchema)
              .set({
                status: newStatus,

                ...(newStatus === 'approved'
                  ? {
                      approved_by: owner_id,
                      approved_at: new Date(),
                    }
                  : {}),
              })
              .where(eq(employeeSalaryEntrySchema.id, id));
            break;

          case 'approve':
            await tx.update(employeeSalaryEntrySchema)
              .set({
                status: 'approved',
                approved_by: owner_id,
                approved_at: new Date(),
              })
              .where(eq(employeeSalaryEntrySchema.id, id));
            break;

          case 'reject':
            await tx.update(employeeSalaryEntrySchema)
              .set({ status: 'cancelled' })
              .where(eq(employeeSalaryEntrySchema.id, id));
            break;

          default:
            errors.push({ id, error: `Unknown action: ${action}` });
            continue;
        }

        processed++;
      } catch (error) {
        errors.push({
          id,
          error: error instanceof Error ? error.message : 'Unknown error',
        });
      }
    }

    return {
      success: errors.length === 0,
      processed,
      failed: errors.length,
      errors,
    };
  });
}
